// src/api/NotificationsApi.js
import { get, post } from './HttpClient';

/**
 * 알림(Notifications) = AI 결과가 있는 로그(aiLabel 존재)
 * 백엔드에 /alerts가 없으므로 /logs + /logs/export(JSON) 를 사용한다.
 *
 * 정책:
 * - level이 DANGER/WARNING/SAFE 인 경우: GET /logs?page&size&aiLabel=... (서버 페이지네이션)
 * - level이 ALL(또는 빈 값)인 경우: POST /logs/export(JSON)로 전체 가져온 뒤
 *   aiLabel 있는 것만 필터링하고, 클라이언트에서 페이지네이션한다.
 */

function toQuery(params = {}) {
  const sp = new URLSearchParams();
  Object.entries(params).forEach(([k, v]) => {
    if (v === undefined || v === null) return;
    const s = String(v).trim();
    if (!s) return;
    sp.set(k, s);
  });
  const qs = sp.toString();
  return qs ? `?${qs}` : '';
}

function isAiAlert(log) {
  const v = (log?.aiLabel ?? '').toString().trim();
  return v.length > 0;
}

function normalizeLevel(level) {
  const v = String(level || '').trim().toUpperCase();
  if (v === 'SAFE' || v === 'WARNING' || v === 'DANGER') return v;
  return ''; // ALL/기타는 빈 문자열로 처리
}

/**
 * fetchAlerts
 * @param {Object} params
 * @param {number} params.page 0-based
 * @param {number} params.size
 * @param {string} params.keyword
 * @param {string} params.level ALL | DANGER | WARNING | SAFE
 * @param {string} params.from YYYY-MM-DD
 * @param {string} params.to YYYY-MM-DD
 * @param {string} params.sort collectedAt,desc 등
 */
export async function fetchAlerts({
  page = 0,
  size = 20,
  keyword = '',
  level = 'ALL',
  from = '',
  to = '',
  sort = 'collectedAt,desc',
} = {}) {
  const lv = normalizeLevel(level);

  // ✅ 특정 레벨이면 서버 페이지네이션 그대로 사용 가능
  if (lv) {
    const res = await get(
      `/logs${toQuery({
        page,
        size,
        keyword,
        aiLabel: lv,
        from,
        to,
        sort,
      })}`
    );

    const items = Array.isArray(res?.items) ? res.items : [];
    // aiLabel 필터를 걸었으니 사실상 전부 알림이지만, 안전하게 한 번 더
    const aiItems = items.filter(isAiAlert);

    return {
      items: aiItems,
      total: typeof res?.total === 'number' ? res.total : aiItems.length,
      page: typeof res?.page === 'number' ? res.page : page,
      size: typeof res?.size === 'number' ? res.size : size,
      mode: 'SERVER_PAGE',
    };
  }

  // ✅ ALL(전체)는 aiLabel 존재 필터를 서버에서 못 하므로 export(JSON)로 전체 가져온 뒤 클라이언트 페이지네이션
  const allItems = await post('/logs/export', {
    format: 'JSON',
    ids: [],
    filters: {
      from,
      to,
      keyword,
      aiLabel: '', // 전체
      eventType: '',
      sort: sort || 'collectedAt,desc',
      // page/size는 export에서 의미 없을 수 있어서 제외해도 됨
    },
  });

  const logs = Array.isArray(allItems) ? allItems : [];
  const aiLogs = logs.filter(isAiAlert);

  const total = aiLogs.length;
  const start = Math.max(0, page) * (Number(size) || 20);
  const end = start + (Number(size) || 20);
  const sliced = aiLogs.slice(start, end);

  return {
    items: sliced,
    total,
    page,
    size,
    mode: 'CLIENT_PAGE',
  };
}

/** 알림 상세 = 로그 상세 */
export function fetchAlertDetail(id) {
  return get(`/logs/${id}`);
}

/**
 * 알림 통계
 * - export(JSON) 기반으로 카운트 산출
 */
export async function fetchAlertStats({
  from = '',
  to = '',
  keyword = '',
  level = 'ALL', // ALL | DANGER | WARNING | SAFE
} = {}) {
  const lv = normalizeLevel(level);

  const items = await post('/logs/export', {
    format: 'JSON',
    ids: [],
    filters: {
      from,
      to,
      keyword,
      aiLabel: lv, // 특정 레벨이면 서버에서 줄여서 내려줌
      eventType: '',
      sort: 'collectedAt,asc',
    },
  });

  const logs = Array.isArray(items) ? items : [];
  const aiLogs = logs.filter(isAiAlert);

  const counter = { total: 0, DANGER: 0, WARNING: 0, SAFE: 0, UNKNOWN: 0 };
  aiLogs.forEach((n) => {
    counter.total += 1;
    const label = (n.aiLabel || 'UNKNOWN').toUpperCase();
    if (counter[label] !== undefined) counter[label] += 1;
    else counter.UNKNOWN += 1;
  });

  return { counter };
}
